 * ternary operators, namely ConditionalExpression
 * and TSConditionalType
 * @param {FastPath} path - The path to the ConditionalExpression/TSConditionalType node.
 * @param {Options} options - Prettier options
 * @param {Function} print - Print function to call recursively
 * @returns {Doc}
 */
function printTernary(path, options, print) {
  const node = path.getValue();
  const isConditionalExpression = node.type === "ConditionalExpression";
  const consequentNodePropertyName = isConditionalExpression
    ? "consequent"
    : "trueType";
  const alternateNodePropertyName = isConditionalExpression
    ? "alternate"
    : "falseType";
  const testNodePropertyNames = isConditionalExpression
    ? ["test"]
    : ["checkType", "extendsType"];
  const consequentNode = node[consequentNodePropertyName];
  const alternateNode = node[alternateNodePropertyName];
  const parts = [];

  // We print a ConditionalExpression in either "JSX mode" or "normal mode".
  // See tests/jsx/conditional-expression.js for more info.
  let jsxMode = false;
  const parent = path.getParentNode();
  const isParentTest =
    parent.type === node.type &&
    testNodePropertyNames.some((prop) => parent[prop] === node);
  let forceNoIndent = parent.type === node.type && !isParentTest;

  // Find the outermost non-ConditionalExpression parent, and the outermost
  // ConditionalExpression parent. We'll use these to determine if we should
  // print in JSX mode.
  let currentParent;
  let previousParent;
  let i = 0;
  do {
    previousParent = currentParent || node;
    currentParent = path.getParentNode(i);
    i++;
  } while (
    currentParent &&
    currentParent.type === node.type &&
    testNodePropertyNames.every(
      (prop) => currentParent[prop] !== previousParent
    )
  );
  const firstNonConditionalParent = currentParent || parent;
  const lastConditionalParent = previousParent;

  if (
    isConditionalExpression &&
    (isJsxNode(node[testNodePropertyNames[0]]) ||
      isJsxNode(consequentNode) ||
      isJsxNode(alternateNode) ||
      conditionalExpressionChainContainsJsx(lastConditionalParent))
  ) {
    jsxMode = true;
    forceNoIndent = true;

    // Even though they don't need parens, we wrap (almost) everything in
    // parens when using ?: within JSX, because the parens are analogous to
    // curly braces in an if statement.
    const wrap = (doc) => [
      ifBreak("("),
      indent([softline, doc]),
      softline,
      ifBreak(")"),
    ];

    // The only things we don't wrap are:
    // * Nested conditional expressions in alternates
    // * null
    // * undefined
    const isNil = (node) =>
      node.type === "NullLiteral" ||
      (node.type === "Literal" && node.value === null) ||
      (node.type === "Identifier" && node.name === "undefined");

    parts.push(
      " ? ",
      isNil(consequentNode)
        ? path.call(print, consequentNodePropertyName)
        : wrap(path.call(print, consequentNodePropertyName)),
      " : ",
      alternateNode.type === node.type || isNil(alternateNode)
        ? path.call(print, alternateNodePropertyName)
        : wrap(path.call(print, alternateNodePropertyName))
    );
  } else {
    // normal mode
    const part = [
      line,
      "? ",
      consequentNode.type === node.type ? ifBreak("", "(") : "",
      align(2, path.call(print, consequentNodePropertyName)),
      consequentNode.type === node.type ? ifBreak("", ")") : "",
      line,
      ": ",
      alternateNode.type === node.type
        ? path.call(print, alternateNodePropertyName)
        : align(2, path.call(print, alternateNodePropertyName)),
    ];
    parts.push(
      parent.type !== node.type ||
        parent[alternateNodePropertyName] === node ||
        isParentTest
        ? part
        : options.useTabs
        ? dedent(indent(part))
        : align(Math.max(0, options.tabWidth - 2), part)
    );
  }

  // We want a whole chain of ConditionalExpressions to all
  // break if any of them break. That means we should only group around the
  // outer-most ConditionalExpression.
  const comments = flat([
    ...testNodePropertyNames.map((propertyName) =>
      getComments(node[propertyName])
    ),
    getComments(consequentNode),
    getComments(alternateNode),
  ]);
  const shouldBreak = comments.some(
    (comment) =>
      isBlockComment(comment) &&
      hasNewlineInRange(
        options.originalText,
        locStart(comment),
        locEnd(comment)
      )
  );
  const maybeGroup = (doc) =>
    parent === firstNonConditionalParent
      ? group(doc, { shouldBreak })
      : shouldBreak
      ? [doc, breakParent]
      : doc;

  // Break the closing paren to keep the chain right after it:
  // (a
  //   ? b
  //   : c
  // ).call()
  const breakClosingParen =
    !jsxMode &&
    (isMemberExpression(parent) ||
      (parent.type === "NGPipeExpression" && parent.left === node)) &&
    !parent.computed;

  const result = maybeGroup([
    printTernaryTest(path, options, print),
    forceNoIndent ? parts : indent(parts),
    isConditionalExpression && breakClosingParen ? softline : "",
  ]);

  return isParentTest ? group([indent([softline, result]), softline]) : result;
}

module.exports = { printTernary };

  // prepend colon to TypeScript type annotation
  if (n.returnType && n.returnType.typeAnnotation) {
    parts.unshift(": ");
  }

  if (n.predicate) {
    // The return type will already add the colon, but otherwise we
    // need to do it ourselves
    parts.push(n.returnType ? " " : ": ", path.call(print, "predicate"));
  }

  return parts;
}

// `ReturnStatement` and `ThrowStatement`
function printReturnAndThrowArgument(path, options, print) {
  const node = path.getValue();
  const semi = options.semi ? ";" : "";
  const parts = [];

  if (node.argument) {
    if (returnArgumentHasLeadingComment(options, node.argument)) {
      parts.push([
        " (",
        indent([hardline, path.call(print, "argument")]),
        hardline,
        ")",
      ]);
    } else if (
      isBinaryish(node.argument) ||
      node.argument.type === "SequenceExpression"
    ) {
      parts.push(
        group([
          ifBreak(" (", " "),
          indent([softline, path.call(print, "argument")]),
          softline,
          ifBreak(")"),
        ])
      );
    } else {
      parts.push(" ", path.call(print, "argument"));
    }
  }

  const comments = getComments(node);
  const lastComment = comments[comments.length - 1];
  const isLastCommentLine = lastComment && isLineComment(lastComment);

  if (isLastCommentLine) {
    parts.push(semi);
  }

  if (hasComment(node, CommentCheckFlags.Dangling)) {
    parts.push(
      " ",
      printDanglingComments(path, options, /* sameIndent */ true)
    );
  }

  if (!isLastCommentLine) {
    parts.push(semi);
  }

  return parts;
}

function printReturnStatement(path, options, print) {
  return ["return", printReturnAndThrowArgument(path, options, print)];
}

function printThrowStatement(path, options, print) {
  return ["throw", printReturnAndThrowArgument(path, options, print)];
}

module.exports = {
  printFunctionDeclaration,
  printArrowFunctionExpression,
  printMethod,
  printReturnStatement,
  printThrowStatement,
  printMethodInternal,
  shouldPrintParamsWithoutParens,
};

// Public verification helper: its defaults come only from the original checkout.
const fs=require('fs'),path=require('path'),{spawnSync}=require('child_process');
const root=process.cwd(),config=JSON.parse(fs.readFileSync('verification.json','utf8')),args=process.argv.slice(2);
const value=name=>{const index=args.indexOf(name);return index<0?undefined:args[index+1];};
const report=path.resolve(value('--report')||'.v4-tmp/public-report.json');fs.mkdirSync(path.dirname(report),{recursive:true});
const selected=value('--tests-json'),tests=selected?JSON.parse(fs.readFileSync(selected,'utf8')):config.publicTests;
const env={...process.env,CI:'true',TZ:'UTC',NODE_ENV:'test',NODE_OPTIONS:'--max-old-space-size=384',SUFFICE_EVAL_REPORT:report};
const execute=(argv,timeout=240000)=>spawnSync(config.nodeRuntime,['--max-old-space-size=384',...argv],{cwd:root,env,encoding:'utf8',windowsHide:true,timeout,maxBuffer:16*1024**2});
for(const build of config.buildSteps){
  const result=execute(build,120000);if(result.stdout)process.stdout.write(result.stdout);if(result.stderr)process.stderr.write(result.stderr);
  if(result.status!==0){fs.writeFileSync(report,JSON.stringify({framework:config.framework,executionFailure:{stage:'build',code:result.status,signal:result.signal,error:result.error?.message,launchErrorCode:result.error?.code,stdout:result.stdout,stderr:result.stderr}}));process.exit(result.status||1);}
}
let invocation;
if(config.framework==='mocha')invocation=['node_modules/mocha/bin/_mocha',...(config.mochaRequires??[]).flatMap(name=>['--require',name]),...tests,'--reporter',path.resolve('.v4-mocha-reporter.cjs'),'--timeout','15000','--exit'];
else if(config.framework==='jest')invocation=['node_modules/jest/bin/jest.js','--runInBand','--watchman=false','--json','--outputFile',report,'--no-cache','--runTestsByPath',...tests];
else if(config.framework==='qunit')invocation=['.v4-qunit-runner.cjs',config.qunitEntry];
else throw new Error('Unknown verified framework');
const result=execute(invocation);if(result.stdout)process.stdout.write(result.stdout);if(result.stderr)process.stderr.write(result.stderr);
if(!fs.existsSync(report))fs.writeFileSync(report,JSON.stringify({framework:config.framework,executionFailure:{stage:'test',code:result.status,signal:result.signal,error:result.error?.message,launchErrorCode:result.error?.code,stdout:result.stdout,stderr:result.stderr}}));
if(result.error)process.stderr.write('\n'+result.error.message+'\n');
console.log('\nVerification report: '+path.relative(root,report));process.exit(result.status??1);

